package com.codeguardian.service; import com.codeguardian.service.ai.config.AIModelConfigManager; import com.codeguardian.service.ai.dto.*; import com.codeguardian.service.ai.factory.AIModelProviderFactory; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.List; @Service @RequiredArgsConstructor public class AIChatService{private final AIModelConfigManager configs;private final AIModelProviderFactory factory;public AIModelResponse chat(String provider,String prompt){return factory.createProvider(configs.getConfig(provider)).chat(AIModelRequest.builder().messages(List.of(AIModelRequest.Message.builder().role("user").content(prompt).build())).temperature(.3).build());}}
